package gen

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"github.com/AtomiCloud/obs/internal/contract"
)

// Marker is the first header line of every generated file (the Go convention for generated code).
const Marker = "Code generated by obs gen. DO NOT EDIT."

// HashPrefix precedes the contract hash in every header.
const HashPrefix = "contract-hash: sha256:"

// HeaderLines are the lines every generated file starts with, without a comment marker:
// the marker, the contract file name and the contract hash.
func HeaderLines(c *contract.Contract) []string {
	return []string{
		Marker,
		"contract: " + ContractPath(c),
		HashPrefix + c.Hash,
	}
}

// ContractPath identifies the source independently of a target or contract hash.
// In a Git repository it is relative to the repository root, even when invoked
// from a service subdirectory. Standalone fixture projects have no .git; their
// contract is relative to the supplied project directory. Synthetic contracts
// keep their supplied logical filename without inspecting unrelated cwd files.
func ContractPath(c *contract.Contract) string {
	name := c.File
	if name == "" {
		return "observability/contract.yaml"
	}
	abs, err := filepath.Abs(name)
	if err != nil {
		return filepath.ToSlash(filepath.Clean(name))
	}
	if _, err := os.Stat(abs); err == nil {
		for dir := filepath.Dir(abs); ; dir = filepath.Dir(dir) {
			if _, err := os.Stat(filepath.Join(dir, ".git")); err == nil {
				if rel, err := filepath.Rel(dir, abs); err == nil {
					return filepath.ToSlash(rel)
				}
			}
			if filepath.Dir(dir) == dir {
				break
			}
		}
	}
	if !filepath.IsAbs(name) {
		return filepath.ToSlash(filepath.Clean(name))
	}
	return filepath.ToSlash(filepath.Join(filepath.Base(filepath.Dir(abs)), filepath.Base(abs)))
}

// ContractOf reads the source path in the generated header, not arbitrary body text.
func ContractOf(content []byte) string {
	head := content
	if len(head) > 600 {
		head = head[:600]
	}
	for _, line := range strings.Split(string(head), "\n") {
		for _, prefix := range []string{"// contract: ", "# contract: "} {
			if strings.HasPrefix(line, prefix) {
				return strings.TrimPrefix(line, prefix)
			}
		}
	}
	return ""
}

// Header is HeaderLines with each line prefixed by prefix ("// ", "# ") and a trailing newline.
func Header(c *contract.Contract, prefix string) string {
	var b strings.Builder
	for _, l := range HeaderLines(c) {
		b.WriteString(prefix)
		b.WriteString(l)
		b.WriteByte('\n')
	}
	return b.String()
}

var hashRe = regexp.MustCompile(HashPrefix + `([0-9a-f]{64})`)

// HashOf reads the contract hash out of a generated file (its first lines); "" if there is none.
func HashOf(content []byte) string {
	head := content
	if len(head) > 600 {
		head = head[:600]
	}
	if m := hashRe.FindSubmatch(head); m != nil {
		return string(m[1])
	}
	return ""
}

// ShortHash is the first 12 hex characters, for messages.
func ShortHash(h string) string {
	if len(h) > 12 {
		return h[:12]
	}
	return h
}

// Problem formats a generated-file failure.
func Problem(path, format string, a ...any) string {
	return fmt.Sprintf("%s: %s", path, fmt.Sprintf(format, a...))
}
